import 'dart:io';
import 'package:sqflite/sqflite.dart' as sqflite;
import 'package:sqflite_common_ffi/sqflite_ffi.dart' as ffi;
import '../../core/profile/countcat_data_paths.dart';
class AppDatabase { AppDatabase._({sqflite.DatabaseFactory? databaseFactory,String? databasePath}):_databaseFactory=databaseFactory,_databasePath=databasePath; static final instance=AppDatabase._(); static const _databaseName='tiktok_seller.db',_schemaVersion=3; sqflite.Database? _database; final sqflite.DatabaseFactory? _databaseFactory; final String? _databasePath;
 factory AppDatabase.inMemoryForTesting(){ffi.sqfliteFfiInit();return AppDatabase._(databaseFactory:ffi.databaseFactoryFfi,databasePath:ffi.inMemoryDatabasePath);}
 Future<sqflite.Database> get database async {if(_database!=null)return _database!; final f=_databaseFactory??_factory(); final p=_databasePath??await _persistentDatabasePath(); _database=await f.openDatabase(p,options:sqflite.OpenDatabaseOptions(version:_schemaVersion,onCreate:_create,onUpgrade:_upgrade)); return _database!;} Future<void> close()async{await _database?.close();_database=null;} sqflite.DatabaseFactory _factory(){if(Platform.isWindows){ffi.sqfliteFfiInit();return ffi.databaseFactoryFfi;}return sqflite.databaseFactory;} Future<String> _persistentDatabasePath() async { final target = await CountCatDataPaths.databaseFile(); if (!target.existsSync() && Platform.isWindows) { final legacy = CountCatDataPaths.legacyDatabase(Directory.current); if (legacy.existsSync()) await legacy.copy(target.path); } return target.path; }
 Future<void> _create(sqflite.Database d,int _) async {await _tables(d);}
 Future<void> _tables(sqflite.DatabaseExecutor d) async {await d.execute('CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL)'); await d.execute('CREATE TABLE accounts (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT \'\',photo_path TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)'); await d.execute('CREATE TABLE account_settings (account_id INTEGER NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(account_id,key))'); await d.execute('CREATE TABLE hpp_master (id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER NOT NULL,name TEXT NOT NULL,unit_amount INTEGER NOT NULL,is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)'); await d.execute('CREATE TABLE live_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER,name TEXT NOT NULL,started_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)'); await d.execute("CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,account_id INTEGER,live_session_id INTEGER,hpp_id INTEGER,hpp_unit_amount INTEGER NOT NULL DEFAULT 0,product_code TEXT NOT NULL,order_id TEXT NOT NULL,quantity INTEGER NOT NULL,gmv_amount INTEGER NOT NULL,payment_description TEXT,payment_status TEXT NOT NULL CHECK(payment_status IN ('pending','paid','cancelled')),paid_at TEXT,net_income_amount INTEGER NOT NULL,order_status TEXT NOT NULL CHECK(order_status IN ('new','dropoff','shipping','closed','returned')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(account_id,order_id))"); await d.execute('CREATE TABLE monthly_reports (account_id INTEGER,year INTEGER NOT NULL,month INTEGER NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,gmv_total INTEGER NOT NULL,net_income_total INTEGER NOT NULL,hpp_total INTEGER NOT NULL,profit_total INTEGER NOT NULL,submitted_at TEXT NOT NULL,UNIQUE(account_id,year,month))'); for(final sql in ['CREATE INDEX tx_account_index ON transactions(account_id)','CREATE INDEX sessions_account_index ON live_sessions(account_id)','CREATE INDEX hpp_account_index ON hpp_master(account_id,is_active)','CREATE INDEX reports_account_index ON monthly_reports(account_id)']){await d.execute(sql);}}
 Future<void> _upgrade(sqflite.Database d,int old,int _) async {if(old>=3)return; await d.transaction((tx)async{for(final t in ['settings','live_sessions','transactions','monthly_reports']){try{await tx.execute('ALTER TABLE $t RENAME TO legacy_$t');}catch(_){}} await _tables(tx); final now=DateTime.now().toUtc().toIso8601String(); final aid=await tx.insert('accounts',{'name':'Default Account','description':'Migrated existing data','created_at':now,'updated_at':now}); await tx.insert('settings',{'key':'active_account_id','value':'$aid','updated_at':now}); try{final s=await tx.query('legacy_settings'); for(final r in s){if(r['key']=='global_hpp'){await tx.insert('hpp_master',{'account_id':aid,'name':'Default HPP','unit_amount':int.tryParse(r['value'] as String)??0,'is_active':1,'created_at':now,'updated_at':now});} else await tx.insert('settings',r);} }catch(_){} try{await tx.execute('INSERT INTO live_sessions(id,account_id,name,started_at,created_at,updated_at) SELECT id,$aid,name,started_at,created_at,updated_at FROM legacy_live_sessions');}catch(_){} try{final h=await tx.query('hpp_master',where:'account_id=?',whereArgs:[aid],limit:1); final amount=h.isEmpty?0:h.single['unit_amount'] as int; await tx.execute('INSERT INTO transactions(id,account_id,live_session_id,hpp_unit_amount,product_code,order_id,quantity,gmv_amount,payment_description,payment_status,paid_at,net_income_amount,order_status,created_at,updated_at) SELECT id,$aid,live_session_id,$amount,product_code,order_id,quantity,gmv_amount,payment_description,payment_status,paid_at,net_income_amount,order_status,created_at,updated_at FROM legacy_transactions');}catch(_){} try{await tx.execute('INSERT INTO monthly_reports(account_id,year,month,period_start,period_end,gmv_total,net_income_total,hpp_total,profit_total,submitted_at) SELECT $aid,year,month,period_start,period_end,gmv_total,net_income_total,hpp_total,profit_total,submitted_at FROM legacy_monthly_reports');}catch(_){} });}
}
